  "function arenaScreen(){\n  const c=arenaCfg(), L=arenaPrecons(), log=arenaLoad(), sm=arenaSummary(log);\n  const head=`<img class=\"title-logo sm\" src=\"${window.ABC_LOGO||''}\" alt=\"Academic Battle Cards\"><h2 class=\"sub-h\">PreCon Arena</h2>`;\n  if(!L.length) return `<div class=\"title-screen sub-screen\">${head}<p class=\"title-sub\">No precon decks found. Run tools/sync_catalog.py with the Precons tab, then rebuild.</p>\n    <div class=\"sub-actions\"><button class=\"toolbtn\" data-do=\"menu\">\\u2039 Back to menu</button></div></div>`;\n  const deckBtns=function(slot,cur){ return L.map(function(p){ return `<button class=\"diff-card ${p.id===cur?'on':''}\" data-do=\"arena-${slot}:${p.id}\">\n      <span class=\"diff-name\">${dmEsc(p.name)}</span><span class=\"diff-blurb\">${p.fe.length} commanders \\u00b7 ${p.ch.length+p.act.length} characters \\u00b7 ${p.ab.length} trivia \\u00b7 ${p.bm.length} Bookmarks \\u00b7 ${p.cr.length} Lenses</span></button>`; }).join(''); };\n  const firstBtns=[['random','Random'],['A','Deck A'],['B','Deck B']].map(function(o){ return `<button class=\"toolbtn${c.first===o[0]?' on':''}\" data-do=\"arena-first:${o[0]}\"${c.first===o[0]?' style=\"outline:2px solid currentColor\"':''}>${o[1]}</button>`; }).join(' ');\n  const pairs=Object.keys(sm.pairs).map(function(k){ const P=sm.pairs[k]; return `<tr><td>${dmEsc(k)}</td><td>${P.n}</td><td>${P.a}</td><td>${P.b}</td><td>${P.d}</td><td>${(P.turns/P.n).toFixed(1)}</td></tr>`; }).join('');\n  const byDeck={}; Object.keys(sm.cards).forEach(function(k){ const C=sm.cards[k]; (byDeck[C.deck]=byDeck[C.deck]||[]).push(C); });\n  const usage=Object.keys(byDeck).map(function(d){ const a=byDeck[d].slice().sort(function(x,y){ return y.used/y.games-x.used/x.games; });\n    const fmt=function(C){ return `${dmEsc(C.name)} <small>(${(C.used/C.games).toFixed(1)}/game)</small>`; };\n    return `<tr><td>${dmEsc(d)}</td><td>${a.slice(0,3).map(fmt).join('<br>')}</td><td>${a.slice(-3).reverse().map(fmt).join('<br>')}</td></tr>`; }).join('');\n  const T='style=\"width:100%;border-collapse:collapse;font-size:.85em;text-align:left\"';\n  const log_=log.games.length?`<h3 class=\"sub-h\" style=\"font-size:1.05em\">Session log \\u2014 ${log.games.length} game${log.games.length>1?'s':''}${sm.decided?` \\u00b7 first player won ${Math.round(100*sm.firstWins/sm.decided)}%`:''}</h3>\n    <table ${T}><tr><th>Matchup (A vs B)</th><th>Games</th><th>A wins</th><th>B wins</th><th>Draws</th><th>Avg turns</th></tr>${pairs}</table>\n    <table ${T}><tr><th>Deck</th><th>Most used</th><th>Least used</th></tr>${usage}</table>`:'<p class=\"title-sub\">No finished games yet this session.</p>';\n  return `<div class=\"title-screen sub-screen arena-screen\">${head}\n    <p class=\"title-sub\">Precon vs precon under the physical precon rules: ${ARENA_RULES.handSize}-card hand, up to ${ARENA_RULES.mulliganMax} mulligans, the first player skips the first draw, ${ARENA_RULES.turnCap}-turn cap.</p>\n    <h3 class=\"sub-h\" style=\"font-size:1.05em\">Deck A \\u2014 you</h3><div class=\"diff-grid\">${deckBtns('a',c.a)}</div>\n    <h3 class=\"sub-h\" style=\"font-size:1.05em\">Deck B \\u2014 AI</h3><div class=\"diff-grid\">${deckBtns('b',c.b)}</div>\n    <h3 class=\"sub-h\" style=\"font-size:1.05em\">Who goes first</h3><div class=\"sub-actions\">${firstBtns}</div>\n    <div class=\"sub-actions\"><button class=\"bigbtn\" data-do=\"arena-start\">Start match \\u203a</button></div>\n    ${log_}\n    <div class=\"sub-actions\"><button class=\"toolbtn\" data-do=\"arena-csv-games\">Export games CSV</button>\n      <button class=\"toolbtn\" data-do=\"arena-csv-cards\">Export cards CSV</button>\n      <button class=\"toolbtn\" data-do=\"arena-clear\">${APP._arenaClearArm?'Tap again to clear':'Clear log'}</button>\n      <button class=\"toolbtn\" data-do=\"menu\">\\u2039 Back to menu</button></div></div>`;\n}",
