  "arenaClick: batch controls",
  "function arenaClick(d){ const c=arenaCfg(), v=d.slice(d.indexOf(':')+1);\n  if(d!=='arena-clear') APP._arenaClearArm=false;\n  if(d.indexOf('arena-a:')===0) c.a=v;\n  else if(d.indexOf('arena-b:')===0) c.b=v;\n  else if(d.indexOf('arena-first:')===0) c.first=v;\n  else if(d==='arena-start'){ arenaStart(); return; }\n  else if(d==='arena-csv-games'||d==='arena-csv-cards'){ const L=arenaLoad(); if(!L.games.length){ toast('No finished games yet.'); return; }\n    if(d==='arena-csv-games') arenaDownload('arena_games.csv',arenaCsv(L.games)); else arenaDownload('arena_cards.csv',arenaCsv(L.cards)); return; }\n  else if(d==='arena-clear'){ if(!APP._arenaClearArm){ APP._arenaClearArm=true; } else { APP._arenaClearArm=false; arenaSave({games:[],cards:[]}); toast('Arena log cleared.'); } }\n  render(); }",
  "function arenaClick(d){ const c=arenaCfg(), v=d.slice(d.indexOf(':')+1);\n  if(d!=='arena-clear') APP._arenaClearArm=false;\n  if(d==='arena-sim-cancel'){ if(APP._sim) APP._sim.cancel=true; arenaSimPaint(); return; }\n  if(APP._sim&&APP._sim.running) return;\n  const sEl=document.getElementById('arena-seed'); if(sEl) c.seed=sEl.value.trim();\n  if(d.indexOf('arena-a:')===0) c.a=v;\n  else if(d.indexOf('arena-b:')===0) c.b=v;\n  else if(d.indexOf('arena-first:')===0) c.first=v;\n  else if(d.indexOf('arena-ctrlA:')===0) c.ctrlA=v;\n  else if(d.indexOf('arena-n:')===0) c.n=+v||1;\n  else if(d==='arena-start'){ arenaStart(); return; }\n  else if(d==='arena-run'){ const seed=c.seed||Math.random().toString(36).slice(2,8);\n    if(c.seed && c.seed.indexOf('#')>0){ /* replay one game: \"batch#n\" */ const bs=c.seed.slice(0,c.seed.lastIndexOf('#')), k=+c.seed.slice(c.seed.lastIndexOf('#')+1)||1;\n      arenaSimRun(1,bs,k-1); return; }\n    arenaSimRun(c.n||100, seed); return; }\n  else if(d==='arena-csv-games'||d==='arena-csv-cards'){ const L=arenaLoad(); if(!L.games.length){ toast('No finished games yet.'); return; }\n    if(d==='arena-csv-games') arenaDownload('arena_games.csv',arenaCsv(L.games)); else arenaDownload('arena_cards.csv',arenaCsv(L.cards)); return; }\n  else if(d==='arena-sim-csv-games'||d==='arena-sim-csv-cards'){ const L=APP._simLog; if(!L||!L.games.length){ toast('Run a batch first.'); return; }\n    const tag=(APP._sim&&APP._sim.seed)||'batch';\n    if(d==='arena-sim-csv-games') arenaDownload('arena_batch_'+tag+'_games.csv',arenaCsv(L.games)); else arenaDownload('arena_batch_'+tag+'_cards.csv',arenaCsv(L.cards)); return; }\n  else if(d==='arena-clear'){ if(!APP._arenaClearArm){ APP._arenaClearArm=true; } else { APP._arenaClearArm=false; arenaSave({games:[],cards:[]}); toast('Arena session cleared.'); } }\n  render(); }\n"
